sys_script_client.script:
function onSubmit() {
    // Get the current value of the 'reason' field
    var newValue = g_form.getValue('reason');

    var modifiedReason = newValue.replace(/,/g, " ");
    var totalCharacters = modifiedReason.length;

    if (totalCharacters > 80) {
        g_form.addErrorMessage("Length of reason cannot exceed 80 characters");
        return false;
    }

    var finalValue = modifiedReason.replace(/\s+/g, ",").trim();

    if (newValue !== finalValue) {
        g_form.setValue('reason', finalValue);
    }
	g_aw.closeRecord();
    return true; // Allow form submission
}
